args.sparql:
SELECT ?airport ?loc ?locLabel WHERE {
  VALUES ?airport { dbr:Valleyview_Airport dbr:Lucknow_Airpark }
  OPTIONAL { ?airport dbo:location ?loc . }
  OPTIONAL { ?airport dbp:location ?loc . }
  OPTIONAL { ?loc rdfs:label ?locLabel . FILTER(lang(?locLabel) = "en") }
}

SELECT ?airport ?country ?countryLabel WHERE {
  VALUES ?airport { dbr:Valleyview_Airport dbr:Lucknow_Airpark }
  OPTIONAL { ?airport dbo:location ?loc . }
  OPTIONAL { ?airport dbp:location ?loc . }
  ?loc (dbo:country|dbp:country) ?country .
  OPTIONAL { ?country rdfs:label ?countryLabel . FILTER(lang(?countryLabel) = "en") }
}

ASK WHERE {
  VALUES ?a1 { dbr:Valleyview_Airport }
  VALUES ?a2 { dbr:Lucknow_Airpark }
  ?a1 (dbo:location|dbp:location) ?loc1 .
  ?a2 (dbo:location|dbp:location) ?loc2 .
  ?loc1 (dbo:country|dbp:country) ?country1 .
  ?loc2 (dbo:country|dbp:country) ?country2 .
  FILTER(?country1 = ?country2)
}

